public static void sort(Comparable[] d){
  int start, end;
  Stack<Integer> sp = new Stack<Integer>();
  sp.push( 0 );
  sp.push( d.length - 1 );
  while( !sp.isEmpty() ){
    end = sp.pop();
    start = sp.pop();
    if(start < end){
      int p = ( start + end ) / 2;
      swap( d, p, start );
      Comparable guide = d[start];
      int i, j = start;
      for(i = start + 1; i <= end; i++ ){
        if( <*1> ){
          j++;
          swap( d, i, j );
        }
      }

      swap( d, start, j );
      sp.push( start );
      sp.push( j - 1 );
      sp.push( j + 1 );
      sp.push( end );
    }
  }
}

public static void swap(Comparable[] d,
int i, int j){
  Comparable t = d[i];
  d[i] = d[j];
  d[j] = t;
}

